def normalize(email):
    return email.strip()


def dedupe_emails(emails):
    seen = set()
    result = []
    for e in emails:
        key = normalize(e)
        if key not in seen:
            seen.add(key)
            result.append(e)
    return result


def is_valid(email):
    try:
        local, domain = email.split("@")
        return bool(local) and "." in domain
    except:
        return False

