from emails import dedupe_emails, is_valid


def test_dedupe_exact():
    assert dedupe_emails(["a@x.com", "b@x.com", "a@x.com"]) == ["a@x.com", "b@x.com"]


def test_is_valid():
    assert is_valid("a@x.com") and not is_valid("nope") and not is_valid("@x.com")

